        let code = gen_module(
            "type User { id: Int, name: Str }\nlet default_user: User = User { id: 1, name: \"x\" }\n",
        )
        .unwrap();
        let file = ast_test::parse(&code);
        let f = ast_test::find_item_fn(&file, "default_user").expect("falta fn default_user");
