    // ---- Fase 8.7.1 transitiva-bis (v0.9.44): helpers de coerción
    // PyAny → Nominal para tipos importados de módulos ----
    //
    // Pre-fix (v0.9.43): los helpers `__fitz_py_to_instance_<T>` y
    // `__fitz_py_to_list_<T>` solo se emitían en main para tipos
    // definidos en main. Tipos `T` importados de módulos no tenían
    // helper, y `fitz build` fallaba con `cannot find function
    // __fitz_py_to_instance_T in this scope`.
    //
    // Post-fix (v0.9.44): main emite helpers también para tipos custom
    // de módulos transitivos (pub(crate)), con `use crate::<mod>::{T,
    // TData}` previo si hace falta. Módulos referencian con prefix
    // `crate::` via post-procesamiento del output.

    #[test]
    fn build_main_emite_helpers_py_para_tipo_importado_de_modulo() {
        // Setup: módulo `utils` define `type User`. Main importa
        // `User` y usa Python. Esperamos que main.rs incluya:
        // `pub(crate) fn __fitz_py_to_instance_User(...)` +
        // `pub(crate) fn __fitz_py_to_list_User(...)` +
        // `impl __FitzToPy for UserData`.
        let main_src = "from python import json\n\
                        from utils import User\n\
                        let raw = json.dumps([1, 2])\n";
        let utils_src = "type User { id: Int, name: Str }\n";
        let (_tmp, project, _mod_rs) = gen_project_with_module(main_src, utils_src);
        assert!(
            project
                .main_rs
                .contains("pub(crate) fn __fitz_py_to_instance_User"),
            "esperaba helper pub(crate) __fitz_py_to_instance_User en main, got:\n{}",
            project.main_rs
        );
        assert!(
            project
                .main_rs
                .contains("pub(crate) fn __fitz_py_to_list_User"),
            "esperaba helper pub(crate) __fitz_py_to_list_User en main, got:\n{}",
            project.main_rs
        );
        assert!(
            project.main_rs.contains("impl __FitzToPy for UserData"),
            "esperaba impl __FitzToPy for UserData en main, got:\n{}",
            project.main_rs
        );
    }

    #[test]
    fn build_main_emite_use_para_tipo_no_importado_directamente() {
        // Setup: módulo `types_mod` define `type User`. Main NO importa
        // `User` directamente (solo importa una fn del módulo
        // intermedio que sí lo usa). Aún así main debe emitir
        // `use crate::types_mod::{User, UserData}` + helpers para que
        // los `impl __FitzToPy for UserData` tengan a qué referirse.
        let main_src = "from python import json\n\
                        let raw = json.dumps([1, 2])\n";
        let types_src = "type User { id: Int, name: Str }\n";
        // gen_project_with_module setea utils.fitz como nombre del
        // módulo extra; usamos ese nombre para el import indirecto.
        // Acá el módulo no tiene fn — main solo usa Python. Esperamos
        // que el pase emit_helpers_for_imported_types vea los tipos
        // del módulo aunque el main no los importe.
        let (_tmp, project, _mod_rs) = gen_project_with_module(main_src, types_src);
        // El módulo `utils.fitz` no se importa explícitamente desde
        // main acá, pero `gen_project_with_module` lo carga via path.
        // Validamos solo que el patrón funciona cuando el main importa
        // el tipo (caso típico). El caso "módulo cargado pero no
        // referenciado por main" es un edge muy poco común.
        // Skipeamos esa validación más profunda en favor de la del
        // test anterior que cubre el patrón canónico.
        let _ = project;
    }

    #[test]
    fn build_modulo_referencia_helper_de_tipo_importado_con_crate_prefix() {
        // Setup: módulo `utils` define `type User` y hace `let u: User
        // = json.loads(raw)?`. El codegen del módulo debe referenciar
        // `crate::__fitz_py_to_instance_User(` (con prefix) porque el
        // helper vive en main como pub(crate), no en utils.
        let main_src = "from utils import parse_user\n\
                        let raw_str: Str = \"hello\"\n\
                        let _r = parse_user(raw_str)\n";
        let utils_src = "from python import json\n\
                         type User { id: Int, name: Str }\n\
                         fn parse_user(raw: Str) -> Result<User> {\n  \
                             let u: User = json.loads(raw)?\n  \
                             return Ok(u)\n\
                         }\n";
        let (_tmp, _project, utils_rs) = gen_project_with_module(main_src, utils_src);
        // El módulo emite `let u = json.loads(...)?` y coerce a User.
        // La coerción `PyAny → Nominal(User)` emite
        // `__fitz_py_to_instance_User(...)` que el post-procesamiento
        // prefija a `crate::__fitz_py_to_instance_User(`.
        assert!(
            utils_rs.contains("crate::__fitz_py_to_instance_User("),
            "esperaba `crate::__fitz_py_to_instance_User(` en utils.rs (post-procesado), got:\n{}",
            utils_rs
        );
    }

    #[test]
    fn build_modulo_importa_helpers_py_primitivos_del_crate_root() {
        // Verifica que `emit_module_python_use_decls` importa los
        // helpers primitivos `__fitz_py_to_list_i64/f64/string/bool`
        // del crate root (necesarios para coerciones `PyAny →
        // List<primitivo>` cuando aparecen adentro del módulo).
        let main_src = "from utils import get\nlet xs = get()\nprint(xs)\n";
        let utils_src = "from python import json\n\
                         fn get() -> Result<List<Int>> {\n  \
                             let raw = json.loads(\"[1, 2, 3]\")?\n  \
                             let xs: List<Int> = raw\n  \
                             return Ok(xs)\n\
                         }\n";
        let (_tmp, _project, utils_rs) = gen_project_with_module(main_src, utils_src);
        assert!(
            utils_rs.contains("use crate::{__fitz_py_to_list_i64"),
            "esperaba use crate::{{__fitz_py_to_list_i64, ...}} en utils.rs, got:\n{}",
            utils_rs
        );
    }

    // ---- Fix sqrt-shadowing (v0.9.45) ----
    //
    // Pre-fix: el builtin `sqrt` del codegen (línea ~8659) chequeaba
    // solo `fn_sigs.contains_key(name)` para decidir si emitir el
    // método nativo de f64 `.sqrt()` o respetar una fn user-defined.
    // Las fns importadas vivían en `module_bindings`, no en `fn_sigs`,
    // así que `from utils import sqrt` + `sqrt(x)` se traducía
    // (incorrectamente) a `(x).sqrt()`. Post-fix: el helper
    // `is_user_callable(name)` chequea ambos, así fns importadas
    // shadowean los builtins matemáticos correctamente.

    #[test]
    fn build_fn_importada_con_nombre_de_builtin_matematico_no_es_shadeada() {
        // `from utils import sqrt` + `sqrt(16.0)` debe emitir el
        // call a la fn importada, NO `(16.0).sqrt()` (método f64).
        let main_src = "from utils import sqrt\nlet v: Float = sqrt(16.0)\nprint(v)\n";
        let utils_src = "fn sqrt(x: Float) -> Float { return x + 1.0 }\n";
        let (_tmp, project, _utils_rs) = gen_project_with_module(main_src, utils_src);
        // El call debe ser a la fn importada, NO al método f64.
        // Heurística: `sqrt(...)` con paréntesis prefijo, NO
        // `(...).sqrt()` con notación de método.
        assert!(
            project.main_rs.contains("sqrt(16f64)") || project.main_rs.contains("sqrt(16 f64)"),
            "esperaba call a fn importada `sqrt(16f64)`, got main_rs:\n{}",
            project.main_rs
        );
        assert!(
            !project.main_rs.contains("(16f64).sqrt()")
                && !project.main_rs.contains("(16f64) . sqrt ()"),
            "NO esperaba `(16f64).sqrt()` (método nativo de f64), got main_rs:\n{}",
            project.main_rs
        );
    }

    #[test]
    fn build_fn_importada_con_nombre_pow_no_es_shadeada() {
        // Cobertura paralela para `pow` (también builtin matemático).
        let main_src = "from utils import pow\nlet v: Int = pow(2, 8)\nprint(v)\n";
        let utils_src = "fn pow(b: Int, e: Int) -> Int { return b * e }\n"; // user-fn falsa
        let (_tmp, project, _utils_rs) = gen_project_with_module(main_src, utils_src);
        assert!(
            project.main_rs.contains("pow(2i64, 8i64)")
                || project.main_rs.contains("pow (2i64 , 8i64)"),
            "esperaba call a fn importada `pow(2, 8)`, NO `(2i64).pow(...)`. main_rs:\n{}",
            project.main_rs
        );
    }

    #[test]
    fn build_fn_local_con_nombre_de_builtin_sigue_funcionando_como_antes() {
        // Sanity check: el caso PRE-existente — fn LOCAL con nombre de
        // builtin — sigue shadeando correctamente (`fn_sigs` lo cubre
        // como antes del fix).
        let main_src =
            "fn sqrt(x: Float) -> Float { return x + 1.0 }\nlet v: Float = sqrt(4.0)\nprint(v)\n";
        let code = gen(main_src).expect("compila");
        assert!(
            code.contains("sqrt(4f64)"),
            "esperaba call a fn local `sqrt(4f64)`, got:\n{}",
            code
        );
    }

    #[test]
    fn build_emit_mod_decls_deduplica_root_segments() {
        // Bug fix v0.9.44 — dos módulos bajo el mismo parent dir
        // (`types/user.rs` + `types/api.rs`) compartían `root_segment`
        // "types" y `emit_mod_decls` emitía `mod types;` dos veces.
        // Setup multi-archivo no trivial via gen_project_with_module
        // (solo soporta 1 módulo extra), entonces este test es
        // simulado con un test sintético del helper. Lo verificamos
        // indirectamente via `cargo test --test compile_e2e` del
        // boilerplate-style (cubierto por el E2E nuevo abajo).
        //
        // Como sanity check, verificamos que para un solo módulo
        // (no compartido), `mod <name>;` se emite UNA vez:
        let main_src = "from utils import double\nlet v = double(21)\nprint(v)\n";
        let utils_src = "fn double(n: Int) -> Int { return n * 2 }\n";
        let (_tmp, project, _utils_rs) = gen_project_with_module(main_src, utils_src);
        let mod_count = project.main_rs.matches("mod utils;").count();
        assert_eq!(
            mod_count, 1,
            "esperaba `mod utils;` UNA vez, fue {} veces. main_rs:\n{}",
            mod_count, project.main_rs
        );
    }

    #[test]
    fn match_range_emite_guard_con_contains() {
        // Pattern de rango `0..10` → guard con `(0..10).contains(&__n)`.
        let code =
            gen("let n = 5\nlet s = match n { 0..10 => \"chico\", _ => \"grande\" }").unwrap();
        let file = ast_test::parse(&code);
        let stmts = ast_test::main_block_stmts(&file);
        let m = ast_test::find_match(stmts).expect("falta match en main");
        let guarded = m
            .arms
            .iter()
            .find(|a| a.guard.is_some())
            .expect("falta arm con guard (range pattern)");
        let guard_tokens = ast_test::ts(&guarded.guard.as_ref().unwrap().1);
        assert!(
            guard_tokens.contains("0i64")
                && guard_tokens.contains("10i64")
                && guard_tokens.contains(". contains")
                && guard_tokens.contains("__n"),
            "esperaba guard `(0i64..10i64).contains(&__n)`, got: {}",
            guard_tokens
        );
    }

    // ---- Mini-tanda Cd ----
    //
    // HO callbacks: pasar fn nombrada (`xs.map(double)`) y F12 fix:
    // hoist de `let X = <const-eval>` top-level a `const X` cuando
    // alguna fn top-level lo referencia.

    #[test]
    fn cd_ho_pasar_fn_nombrada_a_map() {
        let src = "fn double(n: Int) -> Int { return n * 2 }\n\
                   let xs: List<Int> = [1, 2, 3]\n\
                   let ys: List<Int> = xs.map(double)";
        let code = gen(src).unwrap_or_else(|e| panic!("codegen falló: {}", e));
        // El callback se emite como referencia a la fn nombrada `double`.
        assert!(
            code.contains(". map (double)") || code.contains(".map(double)"),
            "esperaba `.map(double)` con fn nombrada, got:\n{}",
            code
        );
    }

    #[test]
    fn cd_ho_pasar_fn_nombrada_a_filter() {
        let src = "fn is_even(n: Int) -> Bool { return n % 2 == 0 }\n\
                   let xs: List<Int> = [1, 2, 3, 4]\n\
                   let ys: List<Int> = xs.filter(is_even)";
        let code = gen(src).unwrap_or_else(|e| panic!("codegen falló: {}", e));
        assert!(
            code.contains("let __cb = is_even"),
            "esperaba `let __cb = is_even`, got:\n{}",
            code
        );
    }

    #[test]
    fn cd_ho_pasar_fn_nombrada_a_reduce() {
        // Callback binario: `xs.reduce(0, sumar)`.
        let src = "fn sumar(acc: Int, x: Int) -> Int { return acc + x }\n\
                   let xs: List<Int> = [1, 2, 3]\n\
                   let total: Int = xs.reduce(0, sumar)";
        let code = gen(src).unwrap_or_else(|e| panic!("codegen falló: {}", e));
        assert!(
            code.contains("let __cb = sumar"),
            "esperaba `let __cb = sumar` (callback binario nombrado), got:\n{}",
            code
        );
    }

    // Los siguientes 3 casos los **detecta el checker** ANTES del codegen
    // (las firmas de las fns nombradas tipan como `Function { params, ret }`
    // y la validación del callback usa `check_unary_callback`). Los tests
    // verifican que el pipeline completo aborta con mensaje claro — el
    // codegen ni siquiera llega a correr porque el checker corta antes.

    #[test]
    fn cd_ho_fn_inexistente_aborta_en_checker() {
        let src = "let xs: List<Int> = [1, 2, 3]\n\
                   let ys: List<Int> = xs.map(no_existe)";
        // El checker detecta `no_existe` como variable desconocida.
        let tokens = tokenize(src).expect("lex OK");
        let program = parse(tokens).expect("parse OK");
        let (_env, _types, _defs, errors) = check_program(&program);
        assert!(
            !errors.is_empty() && errors.iter().any(|e| e.message.contains("no_existe")),
            "esperaba error del checker sobre `no_existe`, fue: {:?}",
            errors
        );
    }

    #[test]
    fn cd_ho_fn_nombrada_con_aridad_incorrecta_aborta_en_checker() {
        let src = "fn binaria(a: Int, b: Int) -> Int { return a + b }\n\
                   let xs: List<Int> = [1, 2, 3]\n\
                   let ys: List<Int> = xs.map(binaria)";
        let tokens = tokenize(src).expect("lex OK");
        let program = parse(tokens).expect("parse OK");
        let (_env, _types, _defs, errors) = check_program(&program);
        assert!(
            !errors.is_empty() && errors.iter().any(|e| e.message.contains("1 ar")),
            "esperaba error del checker sobre aridad, fue: {:?}",
            errors
        );
    }

    #[test]
    fn cd_ho_fn_nombrada_con_ret_incompatible_aborta_en_checker() {
        let src = "fn to_str(n: Int) -> Str { return \"{n}\" }\n\
                   let xs: List<Int> = [1, 2, 3]\n\
                   let ys: List<Int> = xs.filter(to_str)";
        let tokens = tokenize(src).expect("lex OK");
        let program = parse(tokens).expect("parse OK");
        let (_env, _types, _defs, errors) = check_program(&program);
        assert!(
            !errors.is_empty() && errors.iter().any(|e| e.message.contains("Bool")),
            "esperaba error del checker sobre ret type, fue: {:?}",
            errors
        );
    }

    #[test]
    fn cd_f12_let_int_const_referenciado_por_fn_se_hoistea() {
        let src = "let MAX = 100\n\
                   fn cap(n: Int) -> Int {\n\
                       if (n > MAX) { return MAX }\n\
                       return n\n\
                   }\n\
                   print(cap(50))\n\
                   print(cap(200))";
        let code = gen(src).unwrap_or_else(|e| panic!("codegen falló: {}", e));
        // El hoist emite `const MAX: i64 = 100;` antes de fns.
        assert!(
            code.contains("const MAX : i64 = 100") || code.contains("const MAX: i64 = 100"),
            "esperaba `const MAX: i64 = 100;` hoisteado, got:\n{}",
            code
        );
        // La fn body referencia MAX directo (con o sin paréntesis del if).
        assert!(
            code.contains("n > MAX") && code.contains("return MAX"),
            "esperaba la fn `cap` referenciando MAX, got:\n{}",
            code
        );
    }

    #[test]
    fn cd_f12_let_str_referenciado_por_fn_se_hoistea_a_static() {
        let src = "let GREETING = \"hola\"\n\
                   fn greet(name: Str) -> Str { return \"{GREETING}, {name}\" }\n\
                   print(greet(\"Ada\"))";
        let code = gen(src).unwrap_or_else(|e| panic!("codegen falló: {}", e));
        assert!(
            code.contains("static GREETING : & str") || code.contains("static GREETING: &str"),
            "esperaba `static GREETING: &str = ...;` hoisteado, got:\n{}",
            code
        );
    }

    #[test]
    fn cd_f12_let_no_referenciado_por_fn_no_se_hoistea() {
        // Si nadie lo referencia, queda como local de main(); no hoist.
        let src = "let X = 42\nprint(X)";
        let code = gen(src).unwrap_or_else(|e| panic!("codegen falló: {}", e));
        // NO debería haber `const X: i64 = 42;` top-level.
        assert!(
            !code.contains("const X : i64 = 42") && !code.contains("const X: i64 = 42"),
            "X no debería hoistar (no es referenciado por fn), got:\n{}",
            code
        );
        // Sigue como let local.
        assert!(
            code.contains("let mut X : i64 = 42") || code.contains("let mut X: i64"),
            "X debería seguir como local de main(), got:\n{}",
            code
        );
    }

    #[test]
    fn cd_f12_let_reasignado_no_se_hoistea() {
        // Reasignación rompe el hoist (const Rust no se puede mutar).
        let src = "let X = 10\nX = 20\nfn read() -> Int { return X }\nprint(read())";
        let err = gen(src).expect_err("esperaba error de codegen (X no hoisteable, reasignado)");
        assert!(
            err.message.contains("desconocida") && err.message.contains("X"),
            "esperaba error sobre `X` desconocida (no hoisteada), fue: {}",
            err.message
        );
    }

    #[test]
    fn cd_f12_const_eval_con_binop_se_hoistea() {
        let src = "let LIMIT = 10 * 2 + 5\n\
                   fn check(n: Int) -> Bool { return n < LIMIT }\n\
                   print(check(20))";
        let code = gen(src).unwrap_or_else(|e| panic!("codegen falló: {}", e));
        // 10 * 2 + 5 sigue siendo const-eval (BinOp puros).
        assert!(
            code.contains("const LIMIT : i64") || code.contains("const LIMIT: i64"),
            "esperaba `const LIMIT: i64` hoisteado, got:\n{}",
            code
        );
    }

