    #[test]
    fn codegen_orm_navigation_async_block_envolvente() {
        // El terminal navigation es async (devuelve Future<Result<Target>>).
        // El call site `.await?` requiere que el codegen emita un
        // `(async { ... })` para que el chain tipe Rust-side.
        let src = "@table type User {\n  \
                       @primary id: Int = 0\n\
                   }\n\
                   @table type Post {\n  \
                       @primary id: Int = 0\n  \
                       @belongs_to(\"User\") user_id: Int\n\
                   }\n\
                   async fn fetch_user(post: Post) -> Result<User> {\n  \
                       let db = db.connect(\"postgres://x@h/d\").await?\n  \
                       let u = post.user_id(db).await?\n  \
                       return Ok(u)\n\
                   }\n";
        let rust = gen(src).expect("codegen OK");
        assert!(
            rust.contains("(async {"),
            "esperaba async block envolvente, fue: {rust}",
        );
        // Patron específico del helper navigation: __nav_fk, __nav_pg, __nav_qb.
        assert!(
            rust.contains("__nav_fk") && rust.contains("__nav_pg") && rust.contains("__nav_qb"),
            "esperaba bindings __nav_fk/__nav_pg/__nav_qb del helper, fue: {rust}",
        );
    }

    #[test]
    fn codegen_orm_aggregate_emite_async_block_envolvente() {
        // El terminal es async (devuelve Future<Result<Float>>) — el
        // codegen lo envuelve en `(async { ... })` para que `.await?`
        // del call site tipe correcto.
        let src = "@table(\"orders\") type Order {\n  \
                       @primary id: Int = 0\n  \
                       price: Float\n\
                   }\n\
                   async fn boot() -> Result<Null> {\n  \
                       let db = db.connect(\"postgres://x@h/d\").await?\n  \
                       let _t = Order.where(fn(o) => o.price > 100.0).sum(fn(o) => o.price, db).await?\n  \
                       return Ok(null)\n\
                   }\n";
        let rust = gen(src).expect("codegen OK");
        assert!(
            rust.contains("(async {") && rust.contains(".aggregate_f64(&db"),
            "esperaba `(async {{ ... .aggregate_f64(&db, ...) }})`, fue: {rust}",
        );
        // El where previo se preserva en el chain (el helper runtime
        // lo usa para construir `WHERE` antes del aggregate).
        assert!(
            rust.contains(".with_where("),
            "esperaba `.with_where(...)` en el chain antes del aggregate, fue: {rust}",
        );
    }

