    // ---- Fase 10.b.12.a — NULL adentro de arrays (List<scalar?>) ----

    #[test]
    fn codegen_orm_list_int_nullable_inner_emite_vec_option() {
        // Field `tags: List<Int?>` debe deserializar a
        // `Arc<Mutex<Vec<Option<i64>>>>` (cada item puede ser None).
        let src = "@table(\"items\") type Item {\n  \
                       @primary id: Int = 0\n  \
                       tags: List<Int?>\n\
                   }\n\
                   async fn boot() -> Result<List<Item>> {\n  \
                       let db = db.connect(\"postgres://x@h/d\").await?\n  \
                       return Item.all(db).await\n\
                   }\n";
        let rust = gen(src).expect("codegen OK");
        // El struct field debe tipar Vec<Option<i64>>.
        assert!(
            rust.contains("Vec<Option<i64>>") || rust.contains("Vec < Option < i64 > >"),
            "esperaba Vec<Option<i64>> para tags: List<Int?>, fue: {rust}",
        );
        // El deserialize debe usar matches!(__item, ::Null) → None / Some(...).
        assert!(
            rust.contains("matches!(__item, __FitzPgValue::Null)")
                && rust.contains("Some(__fitz_pg_to_i64"),
            "esperaba el branch nullable en deserialize, fue: {rust}",
        );
    }

    #[test]
    fn codegen_orm_list_str_nullable_marshal_some_none() {
        // Field `labels: List<Str?>` debe serializar matcheando
        // Some(__v) → PgValue::Text(__v.clone()) y None → PgValue::Null.
        let src = "@table(\"posts\") type Post {\n  \
                       @primary id: Int = 0\n  \
                       labels: List<Str?>\n\
                   }\n\
                   async fn boot() -> Result<Post> {\n  \
                       let db = db.connect(\"postgres://x@h/d\").await?\n  \
                       let p = Post.insert(db, Post { id: 0, labels: [\"a\", null, \"b\"] }).await?\n  \
                       return Ok(p)\n\
                   }\n";
        let rust = gen(src).expect("codegen OK");
        assert!(
            rust.contains("match __it { Some(__v) =>")
                && rust.contains("__FitzPgValue::Text(__v.clone())")
                && rust.contains("None => __FitzPgValue::Null"),
            "esperaba marshal Some/None → Text/Null, fue: {rust}",
        );
    }

    #[test]
    fn codegen_orm_list_int_nullable_sigue_emitiendo_cast_sql() {
        // `List<Int?>` también necesita `::int8[]` cast en INSERT —
        // Postgres acepta NULL en arrays sin cambiar el tipo del cast.
        let src = "@table(\"items\") type Item {\n  \
                       @primary id: Int = 0\n  \
                       tags: List<Int?>\n\
                   }\n\
                   async fn boot() -> Result<Item> {\n  \
                       let db = db.connect(\"postgres://x@h/d\").await?\n  \
                       return Item.insert(db, Item { id: 0, tags: [1, null, 3] }).await\n\
                   }\n";
        let rust = gen(src).expect("codegen OK");
        assert!(
            rust.contains("::int8[]"),
            "esperaba cast ::int8[] también para nullable inner, fue: {rust}",
        );
    }

    // ---- Fase 10.b.11 — `.update` con List literal / Map literal ----

    #[test]
    fn codegen_update_con_list_literal_emite_pgvalue_array_directo() {
        // `.update(db, {"tags": [1, 2, 3]})` con tags: List<Int>
        // debe emitir __FitzPgValue::Array { elem_oid: INT8, ... } y
        // el SET con cast ::int8[].
        let src = "@table(\"items\") type Item {\n  \
                       @primary id: Int = 0\n  \
                       tags: List<Int>\n\
                   }\n\
                   async fn boot() -> Result<Int> {\n  \
                       let db = db.connect(\"postgres://x@h/d\").await?\n  \
                       let n = Item.where(fn(i) => i.id == 1).update(db, {\"tags\": [10, 20, 30]}).await?\n  \
                       return Ok(n)\n\
                   }\n";
        let rust = gen(src).expect("codegen OK");
        assert!(
            rust.contains("\\\"tags\\\" = $1::int8[]"),
            "esperaba SET con cast ::int8[], fue: {rust}",
        );
        assert!(
            rust.contains("__FitzPgValue::Array") && rust.contains("__fitz_db_runtime::oid::INT8"),
            "esperaba binding directo a __FitzPgValue::Array INT8, fue: {rust}",
        );
        // NO debe haber binding via __IntoPgValue::into_pg para el array.
        assert!(
            !rust.contains("__IntoPgValue>::into_pg(std :: sync :: Arc :: new")
                && !rust.contains("__IntoPgValue>::into_pg(Arc :: new"),
            "no debe pasar el List literal por __IntoPgValue (path roto), fue: {rust}",
        );
    }

    #[test]
    fn codegen_update_con_map_literal_emite_jsonb_via_fitzvalue() {
        // `.update(db, {"meta": {"k": 1, "active": true}})` con
        // meta: Map<Str, Any> debe emitir __FitzPgValue::Text(...)
        // con stringify del __FitzValue::Map. El SET lleva ::jsonb.
        let src = "@table(\"docs\") type Doc {\n  \
                       @primary id: Int = 0\n  \
                       meta: Map<Str, Any>\n\
                   }\n\
                   async fn boot() -> Result<Int> {\n  \
                       let db = db.connect(\"postgres://x@h/d\").await?\n  \
                       let n = Doc.where(fn(d) => d.id == 1).update(db, {\"meta\": {\"k\": 1, \"active\": true}}).await?\n  \
                       return Ok(n)\n\
                   }\n";
        let rust = gen(src).expect("codegen OK");
        assert!(
            rust.contains("\\\"meta\\\" = $1::jsonb"),
            "esperaba SET con cast ::jsonb, fue: {rust}",
        );
        assert!(
            rust.contains("__fitz_fitz_value_to_jsonb") && rust.contains("__FitzValue::Map"),
            "esperaba binding via __fitz_fitz_value_to_jsonb + __FitzValue::Map, fue: {rust}",
        );
    }

